@pytest.mark.parametrize("quantity,expected", [
    (50, 10),   # should be 10% discount
])
def test_bulk_discount_percent_exact_50(quantity, expected):
    assert bulk_discount_percent(quantity) == expected

@pytest.mark.parametrize("code,result", [
    ("SAVE5", 5),
])
def test_parse_coupon_case_insensitive(code, result):
    # The implementation is case sensitive; spec requires insensitive.
    assert parse_coupon(code) == result

@pytest.mark.parametrize("subtotal", [-0.01, -10])
def test_shipping_fee_negative(subtotal):
    with pytest.raises(ValueError):
        shipping_fee(subtotal)

# Remove item: if quantity left <= 0 should delete

def test_remove_item_deletes_when_zero_or_less():
    cart = Cart()
    cart.add_item("tshirt", 20.0, 2)
    # remove exactly the remaining quantity
    cart.remove_item("tshirt", 2)
    assert "tshirt" not in cart.items()

# Remove more than present: should delete (not raise error) but also if qty less? implementation might keep negative.
def test_remove_item_more_than_present():
    cart = Cart()
    cart.add_item("hat", 15.0, 1)
    # removal quantity 2 > existing
    cart.remove_item("hat", 2)
    assert "hat" not in cart.items()

